<script>
document.addEventListener('DOMContentLoaded', () => {
  const field = document.getElementById('integrationField');
  const input = document.getElementById('integrasi_aplikasi');
  const syncIntegrationField = () => {
    const selected = document.querySelector('input[name="jenis_pembinaan"]:checked')?.value;
    const active = selected === 'Integrasi';
    if (field) field.hidden = !active;
    if (input) input.disabled = !active;
  };
  const syncEmployeeRole = (checkbox) => {
    const role = checkbox.closest('.pegawai-check-item')?.querySelector('select[name^="peran"]');
    if (role) role.disabled = !checkbox.checked;
  };
  document.querySelectorAll('input[name="jenis_pembinaan"]').forEach(radio => radio.addEventListener('change', syncIntegrationField));
  document.querySelectorAll('input[name="pegawai[]"]').forEach(checkbox => {
    checkbox.addEventListener('change', () => syncEmployeeRole(checkbox));
    syncEmployeeRole(checkbox);
  });
  syncIntegrationField();
});
function deletePembinaanFile(action){if(!confirm('Hapus file ini?'))return;const f=document.createElement('form');f.method='post';f.action=action;f.innerHTML='<input name="_token" type="hidden" value="{{ csrf_token() }}"><input name="_method" type="hidden" value="DELETE">';document.body.appendChild(f);f.submit()}
</script>
